import {$,esc,money,num,state,api,post,badge,heading,kpis,empty,field,select,toast,dialog,copy,submit,table,bindTables,chart,go,routePage,session} from './app.js';
const currencies=['USD','KES','UGX','CDF','XOF','XAF','RWF','ZMW','SLE'];
const categories=['general','news','technology','sports','business','entertainment','education','travel','lifestyle','gaming'];
const interests=['technology','business','gaming','sports','travel','education','entertainment','shopping'];
const action=(label,key,id,kind='')=>`<button class="btn small ${kind}" data-action="${key}" data-id="${esc(id)}">${label}</button>`;
const safeUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
const dataList=(data)=>`<dl class="dl">${Object.entries(data).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v??'—')}</dd></div>`).join('')}</dl>`;
export async function workspace(v,tab,route){if(tab==='overview')return overview(v);if(tab==='campaign-new')return campaignWizard(v);if(tab==='campaign')return campaignDetails(v,route.split('/')[1]?.split('?')[0]);if(tab==='site')return siteDetails(v,route.split('/')[1]?.split('?')[0]);if(state.user.role==='admin')return admin(v,tab);if(tab==='sites')return sites(v);if(tab==='zones')return zones(v);if(tab==='campaigns')return campaigns(v);if(tab==='analytics')return analytics(v);if(tab==='billing')return billing(v);if(tab==='withdrawals'||tab==='ledger')return ledger(v,tab);if(tab==='standards')return standards(v)}
async function overview(v){const d=state.data,r=state.user.role;if(r==='admin'){v.innerHTML=heading('Network operations','Review the work that needs your attention.')+kpis([['Accounts',num(d.users),'All roles'],['Registered sites',num(d.sites)],['Campaigns',num(d.campaigns)],['Validated spend',money(d.spend)]])+`<div class="grid2"><section class="panel"><div class="section-title"><h2>Site review queue</h2><a class="btn small" href="#/publishers">View all</a></div>${d.pendingSites?.length?queuePreview(d.pendingSites,"site"):empty('No sites waiting','New properties awaiting verification or review appear here.')}</section><section class="panel"><div class="section-title"><h2>Campaign review queue</h2><a class="btn small" href="#/campaigns">View all</a></div>${d.pendingCampaigns?.length?queuePreview(d.pendingCampaigns,"campaign"):empty('Review queue is clear','Campaigns awaiting review will appear here.')}</section></div><section class="panel"><div class="section-title"><h2>Operational workspaces</h2></div><div class="grid3"><div><h3>Money movement</h3><p>Review deposits, payout status and reconciliation.</p><a class="btn" href="#/finance">Transactions ↗</a></div><div><h3>Network protection</h3><p>Inspect invalid events and recorded risk signals.</p><a class="btn" href="#/fraud">Fraud & risk ↗</a></div><div><h3>Customer support</h3><p>Reply to conversations and manage contact channels.</p><a class="btn" href="#/support">Open inbox ↗</a></div></div></section>`;bindReviews(v);return}const publisher=r==='publisher',m=d.metrics||{},views=Number(m.views||0),clicks=Number(m.clicks||0),ctr=views?100*clicks/views:0;const entities=publisher?d.sites:d.campaigns;v.innerHTML=heading(publisher?'Monetization overview':'Performance overview',`Welcome back, ${state.user.name?.split(' ')[0]||'there'}. Here is your workspace at a glance.`,`<a class="btn primary" href="#/${publisher?'sites':'campaign-new'}">${publisher?'Add website':'Create campaign'} ↗</a>`)+kpis([[publisher?'Available balance':'Wallet balance',money(d.balance),'USD · other balances in '+(publisher?'withdrawals':'billing')],[publisher?'Estimated earnings':'Spend',money(publisher?m.revenue:m.spend),'Validated activity'],['Impressions',num(views)],['Clicks / CTR',`${num(clicks)} <span style="font-size:13px">/ ${ctr.toFixed(2)}%</span>`]])+(!entities?.length?empty(publisher?'No monetized sites yet':'No campaigns running yet',publisher?'Add your first property, verify ownership and install an ad zone.':'Create a campaign with your creative, audience and budget.',`<a class="btn primary" href="#/${publisher?'sites':'campaign-new'}">${publisher?'Add website':'Create campaign'}</a>`):`<div class="grid2"><section class="panel"><div class="section-title"><h2>${publisher?'Traffic & earnings':'Campaign delivery'}</h2><a class="btn small" href="#/analytics">Analytics ↗</a></div><div id="overviewChart" class="skeleton"></div></section><section class="panel"><div class="section-title"><h2>${publisher?'Your properties':'Campaign budget usage'}</h2><a class="btn small" href="#/${publisher?'sites':'campaigns'}">View all</a></div><div class="bar-list">${entities.slice(0,6).map(e=>publisher?`<div class="row spread"><a class="text-link" href="#/site/${e.id}">${esc(e.domain)}</a>${badge(e.status)}</div>`:`<div class="bar-row"><a class="text-link" href="#/campaign/${e.id}">${esc(e.name)}</a><span>${money(e.spent_total,e.currency)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,100*Number(e.spent_total||0)/Math.max(1,Number(e.budget_total)))}%"></div></div></div>`).join('')}</div></section></div>`);if($('#overviewChart')){try{const a=await api('/api/analytics/'+r);if(publisher)$('#overviewChart').outerHTML=chart(a.byDay,'revenue','Daily publisher earnings');else $('#overviewChart').outerHTML=`<div class="mini-stats"><div>Active campaigns<strong>${d.campaigns.filter(c=>c.status==='active').length}</strong></div><div>Conversions<strong>${num(a.totals?.conversions)}</strong></div><div>Conversion value<strong>${num(a.totals?.conversion_value)}</strong></div></div><p class="muted">All-time validated totals. Daily advertiser trends are not currently available.</p>`}catch(e){$('#overviewChart').outerHTML=empty('Performance unavailable',e.message)}}}
function sites(v){const rows=state.data.sites||[];v.innerHTML=heading('Websites','Your inventory, ownership proofs and review status.',action('Add website','add-site','', 'primary'))+(rows.length?table(['Website','Verification','Approval','Ads shown','Zones','Actions'],rows.map(s=>({name:s.domain,status:s.status,cells:[`<a class="text-link" href="#/site/${s.id}"><strong>${esc(s.domain)}</strong></a><br><small class="muted">${esc(s.category)}</small>`,badge(s.verification_method?'verified':'pending_verification'),badge(s.status),num(s.ads_shown||0),num((state.data.zones||[]).filter(z=>z.site_id===s.id).length),action('Manage','site',s.id)]})),{name:'websites',filters:['approved','pending_verification','pending_review','rejected']}):empty('No websites added yet','Add a property to start monetizing.',action('Add website','add-site','', 'primary')));v.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>b.dataset.action==='site'?go('site/'+b.dataset.id):addSite())}
function addSite(){const d=dialog('Add a website',`<p>Use a domain you control. Verification instructions stay available in your property workspace.</p><form class="form">${field('domain','Website domain','text','','required placeholder="example.com"')}${select('category','Primary category',categories)}${select('language','Content language',[['en','English'],['sw','Kiswahili'],['fr','French']])}<button type="submit" class="btn primary">Add property</button></form>`);submit(d.querySelector('form'),async data=>{const s=await post('/api/publisher/sites',data);d.close();toast('Website added. Verify ownership next.');go('site/'+s.id)})}
async function siteDetails(v,id){const list=await api('/api/publisher/sites'),s=list.find(x=>x.id===id);if(!s){v.innerHTML=empty('Property not found','Choose a website from your inventory.','<a class="btn" href="#/sites">Back to websites</a>');return}let tab=new URLSearchParams(location.hash.split('?')[1]).get('tab')||'overview';const t=s.verification_token,meta=`<meta name="adpulse-site-verification" content="${t}">`,path='/adpulse-'+t+'.txt',dns='adpulse-verification='+t;v.innerHTML=heading(s.domain,'Property workspace · '+s.category,`<a class="btn" href="https://${esc(s.domain)}" target="_blank" rel="noopener">Visit website ↗</a><a class="btn ghost" href="#/sites">All properties</a>`)+`<div class="segmented detail-tabs">${['overview','verification','zones','standards'].map(k=>`<button data-detail="${k}" class="${tab===k?'active':''}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div><div id="propertyView"></div>`;v.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>go('site/'+id+'?tab='+b.dataset.detail));const p=$('#propertyView');if(tab==='verification'){p.innerHTML=`<section class="panel"><div class="row spread"><h2>Ownership verification</h2>${badge(s.verification_method?'verified':'pending_verification')}</div><p>${s.verification_method?'Verified using '+esc(s.verification_method)+'. Proof details remain available below.':'Choose any supported method, publish the proof, then check verification.'}</p>${s.verified_at?`<small>Verified ${esc(s.verified_at)}</small>`:''}</section><div class="verification"><details open><summary>01 · HTML meta tag — recommended</summary><p>Paste this tag inside the &lt;head&gt; of your homepage.</p><div class="code">${esc(meta)}</div><div class="row">${action('Copy tag','copy-meta',id)}${action('Check meta tag','verify-meta',id,'primary')}</div></details><details open><summary>02 · Verification file</summary><p>Upload a plain text file to the root of your website.</p>${dataList({'Filename':path.slice(1),'Expected URL':'https://'+s.domain+path})}<div class="code">${esc(t)}</div><div class="row">${action('Download file','download',id)}${action('Copy content','copy-file',id)}${action('Check file','verify-file',id,'primary')}</div></details><details open><summary>03 · DNS TXT record</summary><p>Add a TXT record at the root of your domain. DNS changes may take time to propagate.</p>${dataList({'Host':'@','Type':'TXT','Value':dns})}<div class="row">${action('Copy TXT value','copy-dns',id)}${action('Check DNS','verify-dns',id,'primary')}</div></details></div><p class="error" role="alert" id="verificationResult"></p>`;p.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a.startsWith('copy'))return copy(a==='copy-meta'?meta:a==='copy-file'?t:dns);if(a==='download'){const u=URL.createObjectURL(new Blob([t],{type:'text/plain'})),link=document.createElement('a');link.href=u;link.download=path.slice(1);link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return}if(s.verification_method){toast('Ownership is already verified. Existing approval was preserved.');return}b.disabled=true;b.textContent='Checking…';try{const method=a.split('-')[1],r=await post('/api/publisher/sites/'+id+'/verify',{method});if(r.verified){toast(r.status==='approved'?'Ownership verified. Site approved for ads.':'Ownership verified. Your site is pending review.');routePage()}else $('#verificationResult').textContent=method==='dns'?'DNS record not found yet. Confirm the TXT value and allow propagation.':method==='file'?'Verification file missing or its content does not match.':'Meta tag not found. Confirm the exact tag is published in your homepage.'}catch(e){$('#verificationResult').textContent=e.message}finally{b.disabled=false;b.textContent='Check '+a.split('-')[1]}});return}if(tab==='zones'){const z=await api('/api/publisher/zones');p.innerHTML=`<section class="panel"><h2>Ad zones on this website</h2>${zoneRows(z.filter(x=>x.site_id===s.id))}<a class="btn primary" href="#/zones">Manage placements ↗</a></section>`;bindZoneActions(p);return}if(tab==='standards'){p.innerHTML=standardCard(s);bindStandardActions(p);return}p.innerHTML=`<div class="grid2"><section class="panel"><h2>Property status</h2>${dataList({'Domain':s.domain,'Ads shown':num(s.ads_shown||0),'Validated impressions':num(s.impressions||0),'Ad requests':num(s.ad_requests||0),'Category':s.category,'Ownership':s.verification_method?'Verified · '+s.verification_method:'Not verified','Review':s.status.replaceAll('_',' '),'Created':s.created_at,'Seller ID':s.seller_id})}<div class="row"><a class="btn primary" href="#/site/${id}?tab=verification">${s.verification_method?'View verification details':'Verify ownership'}</a><a class="btn" href="#/site/${id}?tab=zones">Ad zones</a></div></section><section class="panel"><h2>Inventory readiness</h2>${checklist(s)}<div class="notice">Verification proves ownership. Ads need an approved site and a one-time zone embed.</div></section></div><section class="panel"><h2>Page context</h2><p>Check the topics and brand-safety classification of your website.</p>${action('Analyze site','analyze',id)}</section>`;p.querySelector('[data-action=analyze]').onclick=async e=>{e.currentTarget.disabled=true;try{const r=await post('/api/publisher/sites/'+id+'/analyze');dialog('Context analysis',dataList({'Category':r.category,'Brand safety':r.brandSafety,'Topics':(r.topics||[]).join(', ')}))}catch(e){toast(e.message)}finally{p.querySelector('[data-action=analyze]').disabled=false}}}
function checklist(s){const zones=(state.data.zones||[]).filter(z=>z.site_id===s.id);return `<div class="checklist">${[['Domain added',true],['Ownership verified',!!s.verification_method],['Site approved',s.status==='approved'],['ads.txt configured',s.ads_txt_status==='verified'],['Ad zone active',zones.some(z=>z.status==='active')]].map(([t,done])=>`<div><i>${done?'✓':'○'}</i><span>${t}</span></div>`).join('')}</div>`}
function standardCard(s){return `<section class="panel"><div class="section-title"><h2>${esc(s.domain)}</h2>${badge(s.status)}</div><div class="grid2"><div>${checklist(s)}</div><div><h3>Authorized inventory</h3><p>Publish this exact line in https://${esc(s.domain)}/ads.txt after site approval.</p><div class="code">${esc(location.hostname)}, ${esc(s.seller_id)}, DIRECT</div><div class="row">${action('Copy ads.txt','copy-ads',s.id)}${action('Check ads.txt','verify-ads',s.id,'primary')}</div><p style="margin-top:15px">Seller registration is available in <a href="/sellers.json" target="_blank">sellers.json</a>. Site approval and policy review govern inventory eligibility.</p></div></div></section>`}
function standards(v){v.innerHTML=heading('Publisher standards','A clear path from ownership to eligible inventory.')+(state.data.sites?.length?state.data.sites.map(standardCard).join(''):empty('Add a website first','Your verification, review and ads.txt checklist will appear here.','<a class="btn primary" href="#/sites">Add website</a>'));bindStandardActions(v)}
function bindStandardActions(v){v.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const s=state.data.sites?.find(s=>s.id===b.dataset.id);if(b.dataset.action==='copy-ads')return copy(location.hostname+', '+s.seller_id+', DIRECT');b.disabled=true;try{const r=await post('/api/publisher/sites/'+b.dataset.id+'/verify-ads-txt');toast(r.verified?'ads.txt verified':'Required line not found: '+r.requiredLine);if(r.verified)routePage()}catch(e){toast(e.message)}finally{b.disabled=false}})}
function zoneRows(rows){return rows.length?table(['Placement','Website','Format','Status','Refresh','Actions'],rows.map(z=>({name:z.name,status:z.status,cells:[`<strong>${esc(z.name)}</strong>`,esc(z.domain||state.data.sites?.find(s=>s.id===z.site_id)?.domain||'—'),esc(z.format),badge(z.status),z.refresh_enabled?`${z.refresh_interval_seconds}s · max ${z.refresh_max}`:'Off',`<div class="row">${action('Install','install',z.id)}${action('Display settings','display',z.id)}${action(z.status==='active'?'Pause':'Resume','zone-status',z.id)}</div>`]})),{name:'zones',filters:['active','paused']}):empty('No ad zones yet','Create a placement on an approved website to receive ads.')}
async function zones(v){const [s,z]=await Promise.all([api('/api/publisher/sites'),api('/api/publisher/zones')]);state.zoneRows=z;state.zoneSites=s;v.innerHTML=heading('Ad zones','Control your inventory without changing your page layout.',action('Create zone','create-zone','', 'primary'))+zoneRows(z);v.querySelector('[data-action=create-zone]').onclick=()=>createZone(s);bindZoneActions(v)}
function createZone(sites){const approved=sites.filter(s=>s.status==='approved');if(!approved.length){toast('Verify a website and complete approval before creating a live zone.');return}const d=dialog('Create an ad zone',`<form class="form">${select('siteId','Approved website',approved.map(s=>[s.id,s.domain]))}${field('name','Placement name','text','','required minlength="2"')}${select('format','Ad format',['responsive','300x250','336x280','728x90','970x250','320x50','320x100','300x600','160x600','native','video'])}${field('floorCpm','Floor CPM','number','0','min="0" step="0.01" required')}<label class="row"><input type="checkbox" name="refreshEnabled"> Enable viewability-aware display refresh</label><div class="grid2">${field('refreshIntervalSeconds','Refresh interval · seconds','number','45','min="30" max="300" required')}${field('refreshMax','Maximum refreshes per page','number','3','min="0" max="10" required')}</div><small class="muted">Native and video do not automatically refresh.</small><button type="submit" class="btn primary">Create zone</button></form>`);submit(d.querySelector('form'),async data=>{data.floorCpm=Number(data.floorCpm);data.refreshEnabled=!!data.refreshEnabled;data.refreshIntervalSeconds=Number(data.refreshIntervalSeconds);data.refreshMax=Number(data.refreshMax);const r=await post('/api/publisher/zones',data);d.close();toast('Zone created');await routePage();dialog('Install your ad zone',`<p>Paste this once into the pages where the zone should appear.</p><div class="code">${esc(r.embed)}</div><button class="btn primary" data-copy>Copy snippet</button>`).querySelector('[data-copy]').onclick=()=>copy(r.embed)})}
function bindZoneActions(v){v.querySelectorAll('[data-action]').forEach(b=>{if(b.dataset.action==='create-zone')return;b.onclick=async()=>{const id=b.dataset.id,z=(state.zoneRows||state.data.zones||[]).find(z=>z.id===id);if(b.dataset.action==='display')return displayEditor(id);if(b.dataset.action==='zone-status'){b.disabled=true;try{await post('/api/publisher/zones/'+id+'/status',{status:z.status==='active'?'paused':'active'});toast('Zone status updated');routePage()}catch(e){toast(e.message)}finally{b.disabled=false}return}if(b.dataset.action==='install'){const snippet=`<div class="adpulse-ad" data-zone="${z.public_key}"></div>\n<script async src="${location.origin}/adpulse.js"></script>`;const d=dialog('Installation · '+z.name,`<p>Install once in your site layout. Choose popup or inline behavior in Display settings. Verification alone does not install a zone.</p><div class="code">${esc(snippet)}</div><div class="row"><button class="btn primary" data-copy>Copy snippet</button><button class="btn" data-preview>Test zone</button></div><div class="notice">A no-fill response can mean no eligible campaign, frequency limits or an unapproved site. This test only reads configuration.</div>`);d.querySelector('[data-copy]').onclick=()=>copy(snippet);d.querySelector('[data-preview]').onclick=async()=>{try{const cfg=await api('/zone-config?zone='+encodeURIComponent(z.public_key));dialog('Zone configuration',dataList({'Format':z.format,'Active':cfg.active??!cfg.settings?.pauseAds,'Mode':cfg.settings?.displayMode,'Popup style':cfg.settings?.popupStyle,'Auto close':cfg.settings?.autoClose,'Rotation interval':cfg.settings?.rotationIntervalSeconds+' seconds'}))}catch(e){toast(e.message)}}}}})}
async function displayEditor(id){const settings=await api('/api/publisher/zones/'+id+'/display-settings');const enums={displayMode:['floating','inline','banner','native'],popupStyle:['floating','center','mixed'],position:['bottom-right','bottom-left','bottom-center'],trigger:['hybrid','time','scroll','engagement','pageview']},limits={initialDelaySeconds:[5,120],minPopupDelaySeconds:[5,120],maxPopupDelaySeconds:[5,300],scrollThreshold:[20,90],scrollTriggerPixels:[0,2000],minPageViews:[2,10],displayDurationSeconds:[15,30],rotationIntervalSeconds:[10,3600],dismissCooldownMinutes:[0,60],maxAdsPerSession:[0,3],maxImpressionsPerCampaignPerSession:[0,3]};const label=k=>k.replace(/([A-Z])/g,' $1').replace(/^./,x=>x.toUpperCase());const d=dialog('Ad display settings',`<p>Settings apply to this zone. Closing an ad is never a billable click.</p><form class="form"><div class="grid2">${Object.entries(settings).map(([k,value])=>enums[k]?select(k,label(k),enums[k],value):typeof value==='boolean'?`<label class="chip"><input type="checkbox" name="${k}" ${value?'checked':''}>${label(k)}</label>`:field(k,label(k),'number',value,`min="${limits[k]?.[0]??0}" max="${limits[k]?.[1]??3600}" required`)).join('')}</div><small class="muted">Time values are seconds except dismissal cooldown (minutes). Zero session caps allow ongoing rotation. Disable Auto close to keep an ad until X. Server frequency limits still apply.</small><button class="btn primary" type="submit">Save settings</button></form>`);submit(d.querySelector('form'),async(_,form)=>{const data={};Object.entries(settings).forEach(([k,value])=>{const x=form.elements[k];data[k]=typeof value==='boolean'?x.checked:typeof value==='number'?Number(x.value):x.value});await post('/api/publisher/zones/'+id+'/display-settings',data);d.close();toast('Display settings saved')})}
async function analytics(v){const role=state.user.role,x=await api('/api/analytics/'+role),t=x.totals||{},publisher=role==='publisher',views=Number(t.views??t.impressions??0),clicks=Number(t.clicks||0);v.innerHTML=heading('Analytics','Validated delivery and outcomes. Refresh when you need the latest view.','<button class="btn" data-refresh>Refresh data ↻</button>')+kpis([['Impressions',num(views)],['Clicks',num(clicks)],['CTR',(views?100*clicks/views:0).toFixed(2)+'%'],[publisher?'Revenue':'Spend',money(publisher?t.revenue:t.spend)]])+`<div class="mini-stats">${publisher?`<div>Ad requests<strong>${num(t.requests)}</strong></div><div>Estimated eCPM<strong>${money(views?1000*Number(t.revenue||0)/views:0)}</strong></div>`:`<div>Conversions<strong>${num(t.conversions)}</strong></div><div>Effective CPM<strong>${money(views?1000*Number(t.spend||0)/views:0)}</strong></div><div>Effective CPC<strong>${money(clicks?Number(t.spend||0)/clicks:0)}</strong></div><div>Cost per conversion<strong>${t.conversions?money(t.spend/t.conversions):'—'}</strong></div>`}</div>`;if(publisher){v.insertAdjacentHTML('beforeend',`<section class="panel"><div class="section-title"><h2>Daily performance</h2></div><div class="filter"><label for="range">Period</label><select id="range"><option value="30">Last 30 days</option><option value="7">Last 7 days</option><option value="1">Today</option></select><label for="metric">Metric</label><select id="metric"><option value="revenue">Earnings</option><option value="views">Impressions</option><option value="clicks">Clicks</option><option value="ctr">CTR</option><option value="ecpm">eCPM</option></select>${field('from','From','date')}${field('to','To','date')}</div><div id="dailyChart"></div></section><div id="dailyTable"></div>`);const update=()=>{const days=Number($('#range').value),cut=new Date();cut.setUTCDate(cut.getUTCDate()-days+1);const from=$('#from').value||cut.toISOString().slice(0,10),to=$('#to').value||'9999';const rows=(x.byDay||[]).filter(r=>r.day>=from&&r.day<=to).map(r=>({...r,ctr:r.views?100*r.clicks/r.views:0,ecpm:r.views?1000*r.revenue/r.views:0}));$('#dailyChart').innerHTML=chart(rows,$('#metric').value,'Daily '+$('#metric').value);$('#dailyTable').innerHTML=rows.length?table(['Day','Requests','Impressions','Clicks','CTR','Earnings'],rows.map(r=>({cells:[esc(r.day),num(r.requests),num(r.views),num(r.clicks),r.ctr.toFixed(2)+'%',money(r.revenue)]})),{name:'days'}):'';bindTables($('#dailyTable'))};['range','metric','from','to'].forEach(id=>$('#'+id).onchange=update);update()}else{const c=state.data.campaigns||[];v.insertAdjacentHTML('beforeend',`<section class="panel"><h2>Campaign spend</h2>${c.length?table(['Campaign','Status','Currency','Spend','Budget'],c.map(c=>({name:c.name,status:c.status,cells:[`<a class="text-link" href="#/campaign/${c.id}">${esc(c.name)}</a>`,badge(c.status),esc(c.currency),money(c.spent_total,c.currency),money(c.budget_total,c.currency)]})),{name:'campaigns',filters:['active','paused','pending_review']}):empty('No traffic recorded','Launch a campaign to start measuring results.')}</section><div class="notice">This view shows account-wide, all-time delivery totals. Campaign budget usage is listed above; detailed delivery breakdowns are not currently available.</div><section class="panel"><h2>Conversion measurement</h2><p>Use your campaign's public pixel key on your success page. Count real outcomes with a unique external order ID.</p><div class="code">&lt;script src="${location.origin}/pixel.js" data-campaign="YOUR_CAMPAIGN_PIXEL_KEY"&gt;&lt;/script&gt;\n&lt;script&gt;ADPulse.track("purchase", {value:100,currency:"USD",externalId:"ORDER-123"})&lt;/script&gt;</div></section>`)}$('[data-refresh]').onclick=()=>routePage()}
async function billing(v){const [me,history,g]=await Promise.all([api('/api/me'),api('/api/payments'),api('/api/payments/gateways').catch(e=>({error:e.message}))]);const gateways=Array.isArray(g)?g:g.gateways||g.data?.gateways||[];const available=[['mobile','Mobile Money Africa'],['card','Card · Visa / Mastercard']];v.innerHTML=heading('Billing','Your wallet, payment methods and funding history.')+kpis((me.balances?.length?me.balances:[{currency:'USD',balance:me.balance}]).map(b=>[b.currency+' wallet',money(b.balance,b.currency)]))+`<div class="grid2"><section class="panel"><h2>Add funds</h2><p>Fund the same currency used by your campaign. Local-currency balances are separate from USD.</p><form class="form" id="fund">${field('amount','Amount','number','','required min="1" step="0.01"')}${select('currency','Currency',currencies)}${select('gateway','Payment method',available)}${field('phone','Mobile number · where required','tel','','autocomplete="tel"')}<div class="notice" id="fundSummary">Enter an amount to see your funding summary. Provider fees and credited amount are confirmed by the payment provider.</div><button class="btn primary" type="submit">Continue to payment ↗</button></form><div id="paymentResult" aria-live="polite"></div>${g.error?`<p class="error">Payment methods could not be checked: ${esc(g.error)}</p>`:''}</section><section class="panel"><h2>Payment safety</h2><p>Funding is credited after provider confirmation. Pending payments stay visible below so you can check their status.</p><div class="checklist"><div><i>01</i> Initiate a payment</div><div><i>02</i> Complete provider checkout or mobile prompt</div><div><i>03</i> Return and confirm your wallet balance</div></div></section></div><section class="panel"><h2>Payment history</h2>${paymentTable(history)}</section>`;const f=$('#fund');const updateCurrency=()=>{const selected=f.currency.value,method=f.gateway.value,metadata=gateways.find(g=>g.id===method),allowed=(metadata?.currencies|| (method==='card'?['USD','KES','UGX']:['KES','UGX','XOF','RWF','ZMW'])).filter(c=>currencies.includes(c));f.currency.innerHTML=allowed.map(c=>`<option value="${c}">${c}</option>`).join('');if(allowed.includes(selected))f.currency.value=selected;f.phone.required=method==='mobile';f.phone.closest('.field').hidden=method==='card';f.querySelector('button[type=submit]').textContent=method==='mobile'?'Send mobile money prompt':'Continue to card checkout';};f.gateway.onchange=updateCurrency;updateCurrency();f.oninput=()=>$('#fundSummary').textContent=`Requested funding: ${money(f.amount.value,f.currency.value)}. Provider fees and final credited amount are confirmed at checkout.`;submit(f,async data=>{data.amount=Number(data.amount);const r=await post('/api/payments/initiate',data);const u=safeUrl(r.redirect_url||r.checkout_url);if(data.gateway==='card'&&u){location.assign(u);return}$('#paymentResult').innerHTML=`<div class="notice">${esc(r.message||'Payment initiated')}<br>Reference: ${esc(r.reference)} ${badge(r.status||'pending')}</div>`;toast('Payment initiated. Complete the provider prompt.');await paymentStatusButton($('#paymentResult'),r.reference,true)});bindPaymentActions(v)}
function paymentTable(rows){return rows?.length?table(['Date','Reference','Kind','Amount','Fee','Status','Actions'],rows.map(p=>({name:p.reference,status:p.status,cells:[esc(p.created_at),esc(p.reference),esc(p.kind),money(p.net_amount||p.amount,p.currency),money(p.fee,p.currency),badge(p.status),p.kind==='deposit'?action('Check status','payment-status',p.reference):'—']})),{name:'payments',filters:['pending','processing','completed','failed','reversed']}):empty('No transactions yet','Your payments and payout activity will appear here.')}
async function paymentStatusButton(el,reference,automatic=false){const b=document.createElement('button');b.className='btn';b.textContent='Check payment status';el.append(b);let attempts=0;const check=async()=>{if(!b.isConnected)return;b.disabled=true;try{const r=await api('/api/payments/'+encodeURIComponent(reference)+'/status'),status=typeof r.status==='string'?r.status:r.status?.status||'pending';b.textContent='Payment: '+status;if(r.credited||status==='completed'){toast('Payment confirmed. Wallet credited.');routePage();return}if(automatic&&['pending','processing'].includes(status)&&++attempts<24)setTimeout(check,5000);else if(['failed','cancelled','reversed'].includes(status))toast('Payment '+status)}catch(e){if(!automatic)toast(e.message);else if(++attempts<24)setTimeout(check,5000)}finally{b.disabled=false}};b.onclick=check;if(automatic)setTimeout(check,5000)}
function bindPaymentActions(v){v.querySelectorAll('[data-action=payment-status]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api('/api/payments/'+encodeURIComponent(b.dataset.id)+'/status');toast('Payment status: '+(r.status||'checked'));routePage()}catch(e){toast(e.message)}finally{b.disabled=false}})}
async function ledger(v,tab){const [x,minimums,history]=await Promise.all([api('/api/ledger'),api('/api/publisher/payout-minimums'),api('/api/payments')]);v.innerHTML=heading(tab==='withdrawals'?'Withdrawals':'Transaction ledger',tab==='withdrawals'?'Move available local-currency earnings to mobile money.':'Earnings, holds and adjustments recorded on your account.')+kpis((x.balances?.length?x.balances:[{currency:'USD',balance:x.balance}]).map(b=>[b.currency+' available',money(b.balance,b.currency)]));if(tab==='withdrawals'){v.insertAdjacentHTML('beforeend',`<div class="grid2"><section class="panel"><h2>Withdraw funds</h2><form class="form" id="withdraw">${select('currency','Payout currency',Object.keys(minimums).filter(c=>c!=='USD'))}${field('amount','Amount','number','','required min="1" step="0.01"')}${field('accountNumber','Mobile money destination','tel','','required minlength="8" maxlength="30"')}<div class="notice" id="payoutSummary"></div><button class="btn primary" type="submit">Review withdrawal</button></form></section></div><section class="panel"><h2>Withdrawal history</h2>${paymentTable(history.filter(p=>p.kind==='withdrawal'))}</section>`);const f=$('#withdraw');const update=()=>{const a=Number(f.amount.value||0),c=f.currency.value,min=minimums[c]||0;f.amount.min=String(min);$('#payoutSummary').textContent=`Minimum ${money(min,c)} · Estimated provider fee ${money(a*.03,c)} · Estimated wallet hold ${money(a*1.03,c)}. Actual provider fee is confirmed with the payout.`};f.oninput=update;update();submit(f,async data=>{data.amount=Number(data.amount);const d=dialog('Confirm withdrawal',`<p>You are requesting ${money(data.amount,data.currency)} to ${esc(data.accountNumber)}. A provider fee applies.</p><div class="row"><button class="btn primary" data-confirm>Confirm payout</button><button class="btn" data-cancel>Cancel</button></div><div class="error" role="alert"></div>`);d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('[data-confirm]').onclick=async e=>{e.currentTarget.disabled=true;try{const r=await post('/api/publisher/withdrawals',data);d.close();toast('Withdrawal '+r.reference+' · '+r.status);routePage()}catch(err){d.querySelector('.error').textContent=err.message;e.currentTarget.disabled=false}}})}else{v.insertAdjacentHTML('beforeend',x.entries.length?table(['Date','Type','Reference','Amount','Status'],x.entries.map(e=>({name:e.type,status:e.status,cells:[esc(e.created_at),esc(e.type.replaceAll('_',' ')),esc(e.event_id||e.id),money(e.amount,e.currency),badge(e.status)]})),{name:'ledger entries',filters:[...new Set(x.entries.map(e=>e.status))]}):empty('No transactions yet','Validated earnings and adjustments will appear in your ledger.'))}}
function campaigns(v){const rows=state.data.campaigns||[];let drafts={};try{drafts=JSON.parse(localStorage.getItem('adpulse_draft_'+state.user.id)||'{}')}catch{}v.innerHTML=heading('Campaigns','Creative, delivery and budgets in one place.','<a class="btn primary" href="#/campaign-new">Create campaign ↗</a>')+(drafts.name?`<div class="notice row spread"><span>Browser draft: ${esc(drafts.name)} · not submitted or serving</span><a class="btn small" href="#/campaign-new">Continue draft</a></div>`:'')+(rows.length?table(['Campaign','Approval','Delivery','Format','Budget','Spend','Schedule','Actions'],rows.map(c=>({name:c.name,status:c.status,cells:[`<a class="text-link" href="#/campaign/${c.id}"><strong>${esc(c.name)}</strong></a><br><small class="muted">${esc(c.model)} · ${esc(c.currency)}</small>`,badge(c.status),c.delivery?(c.delivery.ready?'Eligible to serve':esc(c.delivery.reasons.join(' · '))):'Checking delivery',esc(c.creative_type),money(c.budget_total,c.currency),money(c.spent_total,c.currency),`${esc(c.starts_at?.slice(0,10)||'On approval')}<br><small class="muted">${esc(c.ends_at?.slice(0,10)||'No end date')}</small>`,action('Manage','campaign',c.id)]})),{name:'campaigns',filters:['active','paused','pending_review','completed','rejected']}):empty('No campaigns yet','Create your first campaign with a creative, audience and budget.','<a class="btn primary" href="#/campaign-new">Create campaign</a>'));v.querySelectorAll('[data-action=campaign]').forEach(b=>b.onclick=()=>go('campaign/'+b.dataset.id))}
const creative=c=>{const video=safeUrl(c.video_url||c.videoUrl),image=safeUrl(c.image_url||c.imageUrl),dest=safeUrl(c.destination_url||c.destinationUrl);return `<div class="creative-preview">${(c.creative_type||c.creativeType)==='video'&&video?`<video controls playsinline preload="metadata" src="${esc(video)}"></video>`:image?`<img src="${esc(image)}" alt="Campaign creative" loading="lazy">`:'<div class="empty-icon" style="padding:30px;text-align:center">◇</div>'}<div><small class="muted">Sponsored · creative preview</small><h3 style="margin:8px 0">${esc(c.headline||'Your headline')}</h3><p>${esc(c.description||'Your message will appear here.')}</p>${dest?`<a class="btn small" style="margin-top:14px" target="_blank" rel="noopener" href="${esc(dest)}">Visit destination ↗</a>`:''}</div></div>`};
async function campaignDetails(v,id){const c=(state.data.campaigns||[]).find(c=>c.id===id);if(!c){v.innerHTML=empty('Campaign not found','Choose a campaign from your workspace.','<a class="btn" href="#/campaigns">Back to campaigns</a>');return}v.innerHTML=heading(c.name,'Campaign workspace · '+c.model,`<a class="btn ghost" href="#/campaigns">All campaigns</a>${['active','paused'].includes(c.status)?action(c.status==='active'?'Pause campaign':'Resume campaign','status',id):''}${action('Manage budget','budget',id)}`)+kpis([['Status',badge(c.status)],['Spend',money(c.spent_total,c.currency)],['Total budget',money(c.budget_total,c.currency)],['Daily budget',money(c.budget_daily,c.currency)]])+`<section class="panel"><h2>Delivery readiness</h2><p>${c.delivery?.ready?'Eligible for matching traffic. Frequency limits and competing campaigns still apply.':esc(c.delivery?.reasons?.join(' · ')||'Checking delivery.')}</p>${dataList({'Wallet':money(c.delivery?.balance||0,c.currency),'Matching sites':c.delivery?.matchingSites??'—','Ads shown':num(c.delivery?.ads_shown||0),'Validated impressions':num(c.delivery?.impressions||0)})}<a class="btn" href="#/billing">Add funds</a></section><div class="grid2"><section class="panel"><h2>Creative</h2>${creative(c)}</section><section class="panel"><h2>Targeting & schedule</h2>${dataList({'Countries':JSON.parse(c.target_countries||'[]').join(', ')||'All eligible','Categories':JSON.parse(c.target_categories||'[]').join(', ')||'All eligible','Devices':JSON.parse(c.target_devices||'[]').join(', ')||'All eligible','Interests':JSON.parse(c.target_interests||'[]').join(', ')||'No additional targeting','Excluded interests':JSON.parse(c.exclude_interests||'[]').join(', ')||'None','Frequency cap':c.frequency_cap_daily+' / day','Start':c.starts_at||'After approval','End':c.ends_at||'Not set','CPM':money(c.cpm,c.currency),'CPC':money(c.cpc,c.currency)})}<div class="notice">Creative and targeting are locked after submission. You can pause delivery or increase your budget.</div></section></div><section class="panel"><h2>Conversion pixel</h2><div class="code">&lt;script src="${location.origin}/pixel.js" data-campaign="${esc(c.public_key)}"&gt;&lt;/script&gt;</div><button class="btn" data-copy>Copy pixel snippet</button></section>`;$('[data-copy]').onclick=()=>copy(`<script src="${location.origin}/pixel.js" data-campaign="${c.public_key}"></script>`);v.querySelector('[data-action=status]')?.addEventListener('click',async e=>{e.currentTarget.disabled=true;try{await post('/api/advertiser/campaigns/'+id+'/status',{status:c.status==='active'?'paused':'active'});toast('Campaign status updated');routePage()}catch(e){toast(e.message)}});v.querySelector('[data-action=budget]').onclick=()=>{const d=dialog('Manage campaign budget',`<form class="form">${field('increaseBy','Increase total budget by · '+c.currency,'number','0','min="0" step="0.01" required')}${field('dailyBudget','Daily budget · '+c.currency,'number',c.budget_daily,'min="0.01" step="0.01" required')}<p>Existing spend is preserved. Increasing budget does not automatically fund your wallet.</p><button type="submit" class="btn primary">Update budget</button></form>`);submit(d.querySelector('form'),async data=>{data.increaseBy=Number(data.increaseBy);data.dailyBudget=Number(data.dailyBudget);await post('/api/advertiser/campaigns/'+id+'/budget',data);d.close();toast('Campaign budget updated');routePage()})}}
function chips(name,label,values,selected=[]){return `<div class="field"><label>${label}</label><div class="chips">${values.map(o=>{const [value,text]=Array.isArray(o)?o:[o,o];return `<label class="chip"><input type="checkbox" name="${name}" value="${esc(value)}" ${selected.includes(value)?'checked':''}>${esc(text)}</label>`}).join('')}</div></div>`}
function campaignWizard(v){const key='adpulse_draft_'+state.user.id;let data={name:'',objective:'awareness',creativeType:'display',headline:'',description:'',destinationUrl:'',imageUrl:'',videoUrl:'',model:'CPM',currency:'USD',cpm:1,cpc:.1,budgetTotal:50,budgetDaily:10,frequencyCapDaily:3,conversionWindowDays:7,countries:[],categories:[],devices:[],interests:[],excludeInterests:[],startsAt:'',endsAt:''};try{data={...data,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{}let step=0;const names=['Campaign','Creative','Audience','Budget','Schedule','Review'];const read=()=>{const f=$('#wizardForm');if(!f)return;for(const [k,value]of new FormData(f)){if(['countries','categories','devices','interests','excludeInterests'].includes(k))continue;data[k]=value}if(step===2)for(const k of ['countries','categories','devices','interests','excludeInterests'])data[k]=new FormData(f).getAll(k);for(const k of ['cpm','cpc','budgetTotal','budgetDaily','frequencyCapDaily','conversionWindowDays'])data[k]=Number(data[k]);};const save=()=>{read();localStorage.setItem(key,JSON.stringify(data));toast('Draft saved in this browser. It is not submitted or serving.')};function draw(){v.innerHTML=`<div class="wizard">${heading('Create a campaign','From idea to review, one focused step at a time.','<button class="btn" data-save>Save browser draft</button><a class="btn ghost" href="#/campaigns">Close</a>')}<div class="wizard-layout"><nav class="wizard-steps" aria-label="Campaign steps">${names.map((n,i)=>`<button class="wizard-step ${i===step?'active':i<step?'done':''}" data-step="${i}" ${i>step?'disabled':''}><em>${i<step?'✓':i+1}</em><span>${n}</span></button>`).join('')}</nav><section class="wizard-content"><div class="eyebrow">Step ${step+1} of 6</div><h2>${names[step]}</h2><form class="form" id="wizardForm">${content()}<div class="error" role="alert" id="wizardError"></div><div class="wizard-actions"><button type="button" class="btn" data-back ${step===0?'disabled':''}>Previous</button><button type="submit" class="btn primary">${step===5?'Submit for review ↗':'Continue →'}</button></div></form></section></div></div>`;$('[data-save]').onclick=save;$('[data-back]').onclick=()=>{read();step--;draw()};v.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{read();step=Number(b.dataset.step);draw()});if(step===1){$('#upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;const fd=new FormData();fd.append('file',file);$('#uploadStatus').textContent='Uploading…';try{const r=await api('/api/advertiser/uploads',{method:'POST',body:fd});data[file.type.startsWith('video/')?'videoUrl':'imageUrl']=r.url;data.creativeType=file.type.startsWith('video/')?'video':data.creativeType;draw();$('#uploadStatus').textContent='Creative uploaded'}catch(e){$('#uploadStatus').textContent=e.message}};$('#wizardForm').oninput=()=>{read();$('#creativePreview').innerHTML=creative(data)};$('#creativeType').onchange=()=>{read();draw()}}submit($('#wizardForm'),async()=>{read();if(step===1){const url=data.creativeType==='video'?data.videoUrl:data.imageUrl;if(!url)throw new Error(data.creativeType==='video'?'Upload a video or enter its hosted URL.':'Upload an image or enter its hosted URL.')}if(step===3){if(data.model!=='CPC'&&data.cpm<=0)throw new Error('CPM must be greater than zero.');if(data.model!=='CPM'&&data.cpc<=0)throw new Error('CPC must be greater than zero.');if(data.budgetDaily>data.budgetTotal)throw new Error('Daily budget must not exceed total budget.')}if(step===4&&data.startsAt&&data.endsAt&&new Date(data.endsAt)<=new Date(data.startsAt))throw new Error('End must be after start.');if(step<5){step++;draw();return}const payload={...data};delete payload.objective;for(const k of ['startsAt','endsAt']){if(payload[k])payload[k]=new Date(payload[k]).toISOString();else delete payload[k]}const c=await post('/api/advertiser/campaigns',payload);localStorage.removeItem(key);toast('Campaign submitted for review');go('campaign/'+c.id)})}function content(){if(step===0)return `${field('name','Campaign name','text',data.name,'required minlength="2" maxlength="120"')}${select('objective','Planning objective',[['awareness','Awareness'],['traffic','Website traffic'],['conversions','Conversions']],data.objective)}<small class="muted">Objective organizes your browser draft. Delivery uses your selected pricing and targeting.</small>${select('creativeType','Campaign format',['display','native','video'],data.creativeType)}`;if(step===1)return `<div class="grid2"><div class="form">${select('creativeType','Creative format',['display','native','video'],data.creativeType)}<div class="field"><label for="upload">Upload creative</label><input id="upload" type="file" accept="${data.creativeType==='video'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp,image/gif'}"><small id="uploadStatus" aria-live="polite">Images up to 10 MB · video up to 100 MB</small></div>${field(data.creativeType==='video'?'videoUrl':'imageUrl','Or hosted creative URL','url',data.creativeType==='video'?data.videoUrl:data.imageUrl)}${field('headline','Headline','text',data.headline,'required minlength="2" maxlength="120"')}<div class="field"><label for="description">Description</label><textarea name="description" id="description" maxlength="240">${esc(data.description)}</textarea></div>${field('destinationUrl','Destination URL','url',data.destinationUrl,'required')}</div><div><h3>Live creative preview</h3><div id="creativePreview">${creative(data)}</div></div></div>`;if(step===2)return `<p>Leave a group unselected to allow all eligible matches.</p>${chips('countries','Countries',[['KE','Kenya'],['UG','Uganda'],['TZ','Tanzania'],['RW','Rwanda'],['ZA','South Africa'],['NG','Nigeria'],['US','United States'],['GB','United Kingdom'],['FR','France'],['CD','DR Congo'],['ZM','Zambia']],data.countries)}${chips('categories','Contextual categories',categories,data.categories)}${chips('devices','Devices',['mobile','desktop','tablet'],data.devices)}${chips('interests','Audience interests',interests,data.interests)}${chips('excludeInterests','Excluded interests',interests,data.excludeInterests)}`;if(step===3)return `${select('model','Pricing model',['CPM','CPC','HYBRID'],data.model)}${select('currency','Currency',currencies,data.currency)}<div class="grid2">${field('cpm','CPM · per 1,000 impressions','number',data.cpm,'min="0" step="0.01" required')}${field('cpc','CPC · per click','number',data.cpc,'min="0" step="0.01" required')}${field('budgetTotal','Total budget','number',data.budgetTotal,'min="0.01" step="0.01" required')}${field('budgetDaily','Daily budget','number',data.budgetDaily,'min="0.01" step="0.01" required')}${field('frequencyCapDaily','Per-viewer daily frequency cap','number',data.frequencyCapDaily,'min="1" max="50" required')}${field('conversionWindowDays','Conversion window · days','number',data.conversionWindowDays,'min="1" max="30" required')}</div><p>CPM requires an impression bid. CPC requires a click bid. Hybrid requires both.</p>`;if(step===4)return `${field('startsAt','Starts · optional','datetime-local',data.startsAt)}${field('endsAt','Ends · optional','datetime-local',data.endsAt)}<div class="notice">Times use your browser timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. They are submitted as UTC. Without a start time, delivery begins after review and approval.</div>`;return `<div class="grid2"><div>${creative(data)}</div><div>${dataList({'Campaign':data.name,'Format':data.creativeType,'Pricing':data.model,'Total budget':money(data.budgetTotal,data.currency),'Daily budget':money(data.budgetDaily,data.currency),'Countries':data.countries.join(', ')||'All eligible','Categories':data.categories.join(', ')||'All eligible','Start':data.startsAt||'After approval','End':data.endsAt||'Not set'})}</div></div><div class="notice">Submission sends this campaign to review. It does not guarantee approval or automatically fund your wallet.</div>`}draw()}
function reviewSites(rows){return table(['Website','Publisher','Verification','Status','Ads shown','Actions'],rows.map(s=>({name:s.domain,status:s.status,cells:[`<a class="text-link" href="https://${esc(s.domain)}" target="_blank" rel="noopener">${esc(s.domain)} ↗</a><br><small>${esc(s.category)}</small>`,esc(s.publisher_email),badge(s.verification_method?'verified':'pending_verification'),badge(s.status),num(s.ads_shown||0),`<div class="row">${action('Review','review-site',s.id)}${action('Approve','approve-site',s.id,'primary')}${action('Reject','reject-site',s.id,'danger')}</div>`]})),{name:'sites',filters:['pending_verification','pending_review','approved','rejected']})}
function reviewCampaigns(rows){return table(['Campaign','Advertiser','Format','Pricing','Budget','Actions'],rows.map(c=>({name:c.name,status:c.status,cells:[esc(c.name),esc(c.advertiser_email),esc(c.creative_type),esc(c.model),money(c.budget_total,c.currency),`<div class="row">${action('Review','review-campaign',c.id)}${action('Activate','approve-campaign',c.id,'primary')}${action('Reject','reject-campaign',c.id,'danger')}</div>`]})),{name:'campaigns'})}
function bindReviews(v,sites=state.data.pendingSites,campaigns=state.data.pendingCampaigns){v.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action,id=b.dataset.id;if(a==='review-site'){const s=sites.find(s=>s.id===id);dialog('Site review · '+s.domain,dataList({'Publisher':s.publisher_email,'Domain':s.domain,'Category':s.category,'Verification':s.verification_method||'Not verified','Status':s.status,'Created':s.created_at,'ads.txt':s.ads_txt_status})+'<p>Review history and change-request messaging are not currently available in this workspace.</p>');return}if(a==='review-campaign'){const c=campaigns.find(c=>c.id===id);dialog('Campaign review · '+c.name,creative(c)+dataList({'Advertiser':c.advertiser_email,'Budget':money(c.budget_total,c.currency),'Status':c.status}));return}const kind=a.includes('site')?'sites':'campaigns',status=a.startsWith('reject')?'rejected':kind==='sites'?'approved':'active';const d=dialog('Confirm '+status,`<p>Apply ${status} to this ${kind==='sites'?'website':'campaign'}?</p><button class="btn ${status==='rejected'?'danger':'primary'}" data-confirm>Confirm</button><div class="error" role="alert"></div>`);d.querySelector('[data-confirm]').onclick=async e=>{e.currentTarget.disabled=true;try{await post('/api/admin/'+kind+'/'+id+'/status',{status});d.close();toast('Review status updated');routePage()}catch(err){d.querySelector('.error').textContent=err.message;e.currentTarget.disabled=false}}})}
async function admin(v,tab){if(tab==='zones')return zones(v);if(['advertisers','publisher-accounts'].includes(tab)){const role=tab==='advertisers'?'advertiser':'publisher',users=await api('/api/admin/kyc');v.innerHTML=heading(role==='advertiser'?'Advertisers':'Publishers','Registered accounts from the existing admin profile service.')+accountDirectory(users.filter(u=>u.role===role));bindLoginAs(v);return}if(tab==='publishers'){const [s,policy]=await Promise.all([api('/api/admin/sites'),api('/api/admin/site-policy')]);v.innerHTML=heading('Sites & reviews','Ownership, publisher details and inventory approval.')+`<section class="panel"><label class="chip"><input type="checkbox" id="autoApprove" ${policy.autoApprove?'checked':''}> Automatically approve domains after successful ownership verification</label><p>Unverified domains cannot serve ads. Suspended or rejected sites remain under admin control.</p></section>`+reviewSites(s);$('#autoApprove').onchange=async e=>{try{await post('/api/admin/site-policy',{autoApprove:e.target.checked});toast('Domain approval policy saved')}catch(err){e.target.checked=!e.target.checked;toast(err.message)}};bindReviews(v,s);return}if(tab==='campaigns'){v.innerHTML=heading('Campaign review','Inspect submitted creative and approve eligible demand.')+reviewCampaigns(state.data.pendingCampaigns||[]);bindReviews(v);return}if(tab==='finance'||tab==='withdrawals'){const x=await api('/api/admin/finance');v.innerHTML=heading(tab==='finance'?'Transactions':'Publisher payouts','Provider records and platform reconciliation.',action('Reconcile now','reconcile','','primary'))+kpis((x.totals||[]).map(t=>[t.currency+' funding',money(t.deposits,t.currency),'Payouts '+money(t.withdrawals,t.currency)]))+paymentTable(tab==='withdrawals'?x.recent.filter(p=>p.kind==='withdrawal'):x.recent);$('[data-action=reconcile]').onclick=()=>{const d=dialog('Reconcile payment records','<p>This checks provider status and safely reverses eligible failed payout holds using existing reconciliation logic.</p><button class="btn primary" data-confirm>Run reconciliation</button><div class="error" role="alert"></div>');d.querySelector('[data-confirm]').onclick=async e=>{e.currentTarget.disabled=true;try{const r=await post('/api/admin/finance/reconcile');d.close();toast(`Checked ${r.depositsChecked} deposits and ${r.withdrawalsChecked} payouts; ${r.reversed} reversals.`);routePage()}catch(err){d.querySelector('.error').textContent=err.message;e.currentTarget.disabled=false}}};v.querySelectorAll('[data-action=payment-status]').forEach(b=>b.remove());return}if(tab==='fraud'){const [rows,events]=await Promise.all([api('/api/admin/fraud'),api('/api/admin/fraud/events')]);const invalid=rows.reduce((n,r)=>n+Number(r.invalid_events||0),0),count=rows.reduce((n,r)=>n+Number(r.events||0),0);v.innerHTML=heading('Fraud & risk','Recorded validity and network signals. No inferred capabilities.')+kpis([['Recorded events',num(count)],['Invalid events',num(invalid)],['Invalid rate',(count?100*invalid/count:0).toFixed(2)+'%'],['Recent risk events',num(events.length),'Available event sample']])+`<section class="panel"><h2>Publisher risk summary</h2>${table(['Publisher','Events','Invalid','Invalid rate','Average risk'],rows.map(r=>({name:r.publisher_id,cells:[esc(r.publisher_id),num(r.events),num(r.invalid_events),esc(r.invalid_rate||0)+'%',esc(r.avg_risk||0)]})),{name:'publishers'})}</section><section class="panel"><h2>Recent suspicious events</h2>${table(['Time','Publisher','Type','Risk','Network','Reasons'],events.map(e=>{const n=e.metadata?.network||{};return {cells:[esc(e.created_at),esc(e.publisher_id),esc(e.event_type),esc(e.risk_score),esc([n.asn,n.asnType,n.vpn?'VPN':'',n.proxy?'Proxy':'',n.tor?'Tor':'',n.hosting?'Hosting':''].filter(Boolean).join(' · ')||'—'),esc((e.metadata?.fraudReasons||[]).join(', ')||'—')]}}),{name:'risk events'})}</section>`;return}if(tab==='system'){const [h,profiles]=await Promise.all([api('/api/health'),api('/api/admin/kyc')]);v.innerHTML=heading('System','Service health and available operational surfaces.')+`<section class="panel"><h2>Service status</h2>${dataList({'Service':h.service,'Version':h.version,'API':h.ok?'Healthy':'Unavailable',...Object.fromEntries(Object.entries(h.stores||{}).map(([k,v])=>[k,typeof v==='object'?JSON.stringify(v):v?'Connected':'Unavailable']))})}</section><section class="panel"><h2>Current reporting scope</h2><p>Site review, campaign review, provider reconciliation, support and recorded fraud signals are available. Basic account directories use the existing profile service. Admin time-series charts, review history and per-creative breakdowns are not supplied.</p><p>Server-side role checks, compliance and money movement remain enforced. This frontend does not change those policies.</p></section><section class="panel"><h2>Internal payment eligibility</h2><p>Review existing account eligibility records for protected money movement. Provider checks remain enforced separately.</p>${accountDirectory(profiles,true)}</section>`;bindEligibility(v);bindLoginAs(v);return}if(tab==='support')return adminSupport(v)}
async function adminSupport(v){const [rows,cfg]=await Promise.all([api('/api/admin/support'),api('/api/admin/support/settings')]);v.innerHTML=heading('Support inbox','Respond to visitors and manage contact channels.',action('Contact channels','channels',''))+table(['Updated','Name','Email','Subject','Status','Actions'],rows.map(c=>({name:c.name,status:c.status,cells:[esc(c.updated_at),esc(c.name),esc(c.email),esc(c.subject||'Support'),badge(c.status),action('Open conversation','conversation',c.id)]})),{name:'conversations',filters:[...new Set(rows.map(c=>c.status))]});$('[data-action=channels]').onclick=()=>{const d=dialog('Contact channels',`<form class="form">${field('email','Support email','email',cfg.email,'required')}${field('whatsapp','WhatsApp number','tel',cfg.whatsapp)}<button type="submit" class="btn primary">Save channels</button></form>`);submit(d.querySelector('form'),async data=>{await post('/api/admin/support/settings',data);d.close();toast('Contact channels updated')})};v.querySelectorAll('[data-action=conversation]').forEach(b=>b.onclick=async()=>{const id=b.dataset.id,x=await api('/api/admin/support/'+id);const d=dialog(x.conversation.subject||'Support conversation',`<div class="support-log">${x.messages.map(m=>`<p><strong>${esc(m.sender_type)}:</strong> ${esc(m.body)}</p>`).join('')}</div><form class="form">${field('message','Reply','text','','required')}<button type="submit" class="btn primary">Send reply</button></form>`);submit(d.querySelector('form'),async data=>{await post('/api/admin/support/'+id+'/reply',data);d.close();toast('Reply sent');b.click()})})}


function queuePreview(rows,kind){return `<div class="queue-list">${rows.slice(0,4).map(r=>`<div class="queue-item"><div><strong>${esc(kind==="site"?r.domain:r.name)}</strong><small class="muted">${esc(kind==="site"?r.publisher_email||r.category:r.advertiser_email)}</small></div><div class="row">${badge(r.status)}${action("Review",kind==="site"?"review-site":"review-campaign",r.id)}</div></div>`).join("")}</div>`}

function accountDirectory(users,review=false){return table(['Account','Role','Country','Phone','Created',...(review?['Payment eligibility']:[]),'Actions'],users.map(u=>({name:u.email,status:u.kyc_status,cells:[esc(u.email),badge(u.role),esc(u.country||'—'),esc(u.phone||'—'),esc(u.created_at),...(review?[badge(u.kyc_status||'not_started')]:[]),'<div class="row">'+(review?action('Mark verified','eligibility-verified',u.id)+action('Reject','eligibility-rejected',u.id,'danger'):'')+action('Log in as user','login-as',u.id)+'</div>']})),{name:'accounts'})}
function bindEligibility(v){v.querySelectorAll('[data-action^=eligibility-]').forEach(b=>b.onclick=()=>{const status=b.dataset.action.split('-')[1],d=dialog('Confirm payment eligibility',`<p>Apply ${esc(status)} to this account's internal payment-eligibility record?</p><button class="btn primary" data-confirm>Confirm change</button><div class="error" role="alert"></div>`);d.querySelector('[data-confirm]').onclick=async e=>{e.currentTarget.disabled=true;try{await post('/api/admin/kyc/'+b.dataset.id+'/status',{status});d.close();toast('Payment eligibility updated');routePage()}catch(err){d.querySelector('.error').textContent=err.message;e.currentTarget.disabled=false}}})}


function bindLoginAs(v){v.querySelectorAll('[data-action=login-as]').forEach(b=>b.onclick=()=>{const d=dialog('Log in as user','<p>Open a recorded 15-minute support session. Payment and withdrawal actions are disabled. You can return to your admin account at any time.</p><button class="btn primary" data-confirm>Start support session</button><div class="error" role="alert"></div>');d.querySelector('[data-confirm]').onclick=async e=>{e.currentTarget.disabled=true;try{const r=await post('/api/admin/users/'+b.dataset.id+'/login-as',{});sessionStorage.setItem('adpulse_support_admin',localStorage.getItem('adpulse_token'));d.close();session(r)}catch(err){d.querySelector('.error').textContent=err.message;e.currentTarget.disabled=false}}})}
